  Lemma ipf_after_tab : forall (LF : list fframe) (m m1 m2 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
      (ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
      (P IN E p0 : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (q : Z) (E1 : ecv) (g : bool)
      (lo shi ff fp last : Z) (h0 h1 h2 h3 : word) (shb j0 j128 jr jh : list byte) (XS : list (Z * Z))
      (jt : list byte) (p' bsz : Z) (bb : list byte) (vl nm : list cell),
    ipf_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q (ErrCodeCells E1) g
            lo shi ff fp last h0 h1 h2 h3 shb j0 j128 jr jh XS ->
    ipf_frame m1 spa ff jt p' bsz bb vl nm ->
    ipf_bpure sp spa gsz P IN E lo shi c p0 last bs ->
    munch [(lo, spa); (AG_FIELD_TABLE, AG_FIELD_TABLE + 3456)] m1 m2 ->
    wmono asegs m1 m2 -> mem_inv asegs m2 -> stk asegs m2 lo spa ->
    (AFieldTabZero m2 \/ FT m2) -> FTInit m2 -> ACONST m2 ->
       ipf_ctx H LF m m2 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q (ErrCodeCells E1) g
               lo shi ff fp last h0 h1 h2 h3 shb j0 j128 jr jh XS
    /\ ipf_frame m2 spa ff jt p' bsz bb vl nm
    /\ (forall A xs, bytes_at asegs m1 A xs -> p0 <= A -> A + Z.of_nat (length xs) <= p0 + Z.of_nat (length bs) -> bytes_at asegs m2 A xs)
    /\ (forall (s : as_St H) LB, as_RHEAP H s LB m1 -> as_RHEAP H s LB m2).
